}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class CurrencyService {
    public BigDecimal convert(BigDecimal amount, String from, String to, String tier) {
        BigDecimal inPln = amount.multiply(rate(from)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(rate(to), 4, RoundingMode.HALF_UP);
        if (!"STAFF".equals(tier)) {
            result = result.multiply(new BigDecimal("0.985"));
        }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }

    private BigDecimal rate(String currency) {
        if ("EUR".equals(currency)) return new BigDecimal("4.30");
        if ("USD".equals(currency)) return new BigDecimal("4.00");
        return BigDecimal.ONE.setScale(2);
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

public class DailyStats {
    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();

    public void count(String date, int slot) {
        if (date == null) return;
        counts.computeIfAbsent(date, d -> new int[2])[slot]++;
    }

    public int getOk(String date) {
        int[] c = counts.get(date);
        return c == null ? 0 : c[0];
    }

    public int getRejected(String date) {
        int[] c = counts.get(date);
        return c == null ? 0 : c[1];
    }

    public Map<String, BigDecimal> getFees(String date) {
        return fees.getOrDefault(date, new TreeMap<>());
    }

    public void addFee(String date, String currency, BigDecimal delta) {
        if (delta.signum() == 0) return;
        fees.computeIfAbsent(date, d -> new TreeMap<>())
            .merge(currency, delta, BigDecimal::add);
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class FeeService {
    public BigDecimal calculateTransferFee(String tier, BigDecimal amount) {
        if ("STAFF".equals(tier)) return BigDecimal.ZERO.setScale(2);
        if ("STANDARD".equals(tier)) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.20"));
        }
        BigDecimal fee = amount.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP);
        return fee.max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
    }

    public BigDecimal calculateWithdrawalFee(String tier) {
        return "STANDARD".equals(tier) ? new BigDecimal("1.00") : BigDecimal.ZERO.setScale(2);
    }
}

package com.rustyledger;

import java.math.BigDecimal;

public record Instruction(
    String verb,
    String date,
    String from,
    String to,
    BigDecimal amount,
    String currency,
    String txId,
    String error,
    String message
) {}

package com.rustyledger;

import java.math.BigDecimal;

public class Parser {
    public Instruction parse(String line) {
        if (line == null || line.trim().isEmpty()) {
            return new Instruction("???", null, null, null, null, null, null, "BAD_INSTRUCTION", "empty instruction");
        }
        String[] f = line.split("\\|", -1);
        String verb = f[0];
        if (!isVerb(verb)) return new Instruction("???", null, null, null, null, null, null, "BAD_INSTRUCTION", "unknown verb " + verb);
        int want = expected(verb);
        if (f.length != want) return new Instruction(verb, null, null, null, null, null, null, "BAD_INSTRUCTION", verb + " needs " + want + " fields");
        if (!f[1].matches("\\d{4}-\\d{2}-\\d{2}")) return new Instruction(verb, null, null, null, null, null, null, "BAD_DATE", f[1]);
        if ("REVERSE".equals(verb)) return new Instruction(verb, f[1], null, null, null, null, f[2], null, null);
        return parseWithAmount(verb, f);
    }

    private Instruction parseWithAmount(String verb, String[] f) {
        String amountText = "TRANSFER".equals(verb) ? f[4] : f[3];
        if (!amountText.matches("\\d+(\\.\\d{1,2})?")) {
            return new Instruction(verb, f[1], null, null, null, null, null, "BAD_AMOUNT", amountText);
        }
        BigDecimal amount = new BigDecimal(amountText).setScale(2);
        if (amount.signum() <= 0) return new Instruction(verb, f[1], null, null, null, null, null, "BAD_AMOUNT", amountText);
        if ("TRANSFER".equals(verb)) return new Instruction(verb, f[1], f[2], f[3], amount, f[5], null, null, null);
        return new Instruction(verb, f[1], f[2], null, amount, null, null, null, null);
    }

    private boolean isVerb(String v) {
        return "TRANSFER".equals(v) || "WITHDRAW".equals(v) || "DEPOSIT".equals(v) || "REVERSE".equals(v);
    }

    private int expected(String v) {
        if ("TRANSFER".equals(v)) return 6;
        if ("REVERSE".equals(v)) return 3;
        return 4;
    }
}

package com.rustyledger;

public record TxRecord(
    String verb,
    String date,
    String from,
    String to,
    String amount,
    String cur,
    String fee,
    String credited,
    boolean reversed
) {
    public TxRecord withReversed() {
        return new TxRecord(verb, date, from, to, amount, cur, fee, credited, true);
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.Map;

public class Engine {
    private final Map<String, Account> accounts;
    private final Map<String, TxRecord> txs;
    private final DailyStats stats;
    private final AuditLog audit;
    private final FeeService fees;
    private final CurrencyService exchange;
    private int txSeq = 0;

    public Engine(Map<String, Account> a, Map<String, TxRecord> t, DailyStats s, AuditLog l) {
        this.accounts = a; this.txs = t; this.stats = s; this.audit = l;
        this.fees = new FeeService(); this.exchange = new CurrencyService();
    }

    public String execute(Instruction i) {
        return switch (i.verb()) {
            case "TRANSFER" -> transfer(i);
            case "WITHDRAW" -> withdraw(i);
            case "DEPOSIT" -> deposit(i);
            case "REVERSE" -> reverse(i);
            default -> reject("???", null, "BAD_INSTRUCTION", "unknown verb " + i.verb());
        };
    }

    private String transfer(Instruction i) {
        Account from = accounts.get(i.from());
        Account to = accounts.get(i.to());
        if (from == null) return reject("TRANSFER", i.date(), "UNKNOWN_ACCOUNT", i.from());
        if (to == null) return reject("TRANSFER", i.date(), "UNKNOWN_ACCOUNT", i.to());
        if (i.from().equals(i.to())) return reject("TRANSFER", i.date(), "SAME_ACCOUNT", "cannot transfer to the same account");
        if (!from.currency.equals(i.currency())) return reject("TRANSFER", i.date(), "CURRENCY_MISMATCH", from.id + " holds " + from.currency);
        BigDecimal fee = fees.calculateTransferFee(from.tier, i.amount());
        String rejection = checkLimitAndFunds(i.date(), from, i.amount(), fee);
        if (rejection != null) return reject("TRANSFER", i.date(), rejection.split(":")[0], rejection.split(": ")[1]);
        BigDecimal credited = from.currency.equals(to.currency) ? i.amount() : exchange.convert(i.amount(), from.currency, to.currency, from.tier);
        from.balance = from.balance.subtract(i.amount().add(fee));
        to.balance = to.balance.add(credited);
        from.addUsage(i.date(), i.amount());
        String id = nextId();
        txs.put(id, new TxRecord("TRANSFER", i.date(), i.from(), i.to(), i.amount().toString(), from.currency, fee.toString(), credited.toString(), false));
        stats.addFee(i.date(), from.currency, fee);
        return accept("TRANSFER", i.date(), id, "fee=" + fee + " " + from.currency);
    }

    private String withdraw(Instruction i) {
        Account a = accounts.get(i.from());
        if (a == null) return reject("WITHDRAW", i.date(), "UNKNOWN_ACCOUNT", i.from());
        BigDecimal fee = fees.calculateWithdrawalFee(a.tier);
        String rejection = checkLimitAndFunds(i.date(), a, i.amount(), fee);
        if (rejection != null) return reject("WITHDRAW", i.date(), rejection.split(":")[0], rejection.split(": ")[1]);
        a.balance = a.balance.subtract(i.amount().add(fee));
        a.addUsage(i.date(), i.amount());
        String id = nextId();
        txs.put(id, new TxRecord("WITHDRAW", i.date(), i.from(), "", i.amount().toString(), a.currency, fee.toString(), i.amount().toString(), false));
        stats.addFee(i.date(), a.currency, fee);
        return accept("WITHDRAW", i.date(), id, "fee=" + fee + " " + a.currency);
    }

    private String deposit(Instruction i) {
        Account a = accounts.get(i.from());
        if (a == null) return reject("DEPOSIT", i.date(), "UNKNOWN_ACCOUNT", i.from());
        a.balance = a.balance.add(i.amount());
        String id = nextId();
        txs.put(id, new TxRecord("DEPOSIT", i.date(), i.from(), "", i.amount().toString(), a.currency, "0.00", i.amount().toString(), false));
        return accept("DEPOSIT", i.date(), id, "fee=0.00 " + a.currency);
    }

    private String reverse(Instruction i) {
        TxRecord tx = txs.get(i.txId());
        if (tx == null) return reject("REVERSE", i.date(), "UNKNOWN_TX", i.txId());
        if (!"TRANSFER".equals(tx.verb())) return reject("REVERSE", i.date(), "NOT_REVERSIBLE", i.txId() + " is a " + tx.verb());
        if (tx.reversed()) return reject("REVERSE", i.date(), "ALREADY_REVERSED", i.txId());
        if (!tx.date().equals(i.date())) return reject("REVERSE", i.date(), "REVERSAL_WINDOW", i.txId() + " was made on " + tx.date());
        Account from = accounts.get(tx.from());
        Account to = accounts.get(tx.to());
        BigDecimal fee = new BigDecimal(tx.fee());
        to.balance = to.balance.subtract(new BigDecimal(tx.credited()));
        BigDecimal back = new BigDecimal(tx.amount());
        if ("PREMIUM".equals(from.tier)) {
            back = back.add(fee);
            stats.addFee(i.date(), from.currency, fee.negate());
        }
        from.balance = from.balance.add(back);
        txs.put(i.txId(), tx.withReversed());
        String id = nextId();
        txs.put(id, new TxRecord("REVERSE", i.date(), tx.from(), tx.to(), tx.amount(), tx.cur(), "0.00", tx.credited(), true));
        return accept("REVERSE", i.date(), id, "reversed " + i.txId());
    }

    private String checkLimitAndFunds(String date, Account a, BigDecimal amount, BigDecimal fee) {
        BigDecimal limit = switch(a.tier) {
            case "STANDARD" -> new BigDecimal("5000.00");
            case "PREMIUM" -> new BigDecimal("20000.00");
            default -> new BigDecimal("50000.00");
        };
        if (a.getUsed(date).add(amount).compareTo(limit) > 0) return "LIMIT_EXCEEDED: daily limit " + limit + " for " + a.tier;
        BigDecimal needed = amount.add(fee);
        BigDecimal overdraft = "PREMIUM".equals(a.tier) ? new BigDecimal("500.00") : BigDecimal.ZERO;
        if (a.balance.subtract(needed).compareTo(overdraft.negate()) < 0) {
            return "INSUFFICIENT_FUNDS: balance " + a.balance + " " + a.currency + ", needed " + needed + " " + a.currency;
        }
        return null;
    }

    public String reject(String verb, String date, String code, String message) {
        stats.count(date, 1);
        audit.record(verb, date, "REJECTED " + code);
        return "REJECTED " + code + ": " + message;
    }

    private String accept(String verb, String date, String id, String extra) {
        stats.count(date, 0);
        audit.record(verb, date, "OK " + id);
        return "OK " + id + " " + extra;
    }

    private String nextId() { return String.format("TX-%06d", ++txSeq); }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class LedgerImpl implements Ledger {
    private final Map<String, Account> accounts = new HashMap<>();
    private final Map<String, TxRecord> txs = new LinkedHashMap<>();
    private final DailyStats stats = new DailyStats();
    private final AuditLog audit = new AuditLog();
    private final Parser parser = new Parser();
    private final Engine engine = new Engine(accounts, txs, stats, audit);

    public void openAccount(String id, String tier, String cur, String bal) {
        if (id == null || id.trim().isEmpty() || id.contains("|")) throw new IllegalArgumentException("INVALID ACCOUNT ID");
        if (!List.of("STANDARD", "PREMIUM", "STAFF").contains(tier)) throw new IllegalArgumentException("INVALID TIER: " + tier);
        if (!List.of("PLN", "EUR", "USD").contains(cur)) throw new IllegalArgumentException("INVALID CURRENCY: " + cur);
        if (bal == null || !bal.matches("\\d+(\\.\\d{1,2})?")) throw new IllegalArgumentException("INVALID AMOUNT: " + bal);
        if (accounts.containsKey(id)) throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        accounts.put(id, new Account(id, tier, cur, new BigDecimal(bal)));
    }

    public String submit(String line) {
        Instruction i = parser.parse(line);
        if (i.error() != null) return engine.reject(i.verb(), i.date(), i.error(), i.message());
        return engine.execute(i);
    }

    public String balance(String id) {
        Account a = accounts.get(id);
        if (a == null) throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        return a.balance + " " + a.currency;
    }

    public List<String> auditLog() { return audit.getLines(); }

    public String dailyReport(String date) {
        Map<String, BigDecimal> fMap = stats.getFees(date);
        StringBuilder sb = new StringBuilder();
        fMap.forEach((cur, amt) -> {
            if (sb.length() > 0) sb.append(", ");
            sb.append(amt).append(" ").append(cur);
        });
        String feesText = sb.length() == 0 ? "none" : sb.toString();
        return String.format("REPORT %s\nok: %d\nrejected: %d\nfees: %s", date, stats.getOk(date), stats.getRejected(date), feesText);
    }
}

